import { test, expect } from '@playwright/test';

test.describe('Checkout Form Validation - Required Fields', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
    await page.getByRole('button', { name: /sign in/i }).click();
    await page.getByLabel(/standard_user/i).click();
    await page.getByLabel(/secret_sauce/i).click();
    await page.getByRole('button', { name: /sign in/i }).click();
    await page.getByRole('button', { name: /sign up/i }).click();
    await page.getByLabel(/standard_user/i).click();
    await page.getByLabel(/secret_sauce/i).click();
    await page.getByRole('button', { name: /sign in/i }).click();
  });

  test('should display error when postal code is missing', async ({ page }) => {
    await page.getByRole('button', { name: /add to cart/i }).click();
    await page.getByRole('button', { name: /add to cart/i }).click();
    await page.getByRole('button', { name: /add to cart/i }).click();
    await page.getByRole('button', { name: /add to cart/i }).click();
    await page.getByRole('button', { name: /checkout/i }).click();

    const firstNameInput = page.getByLabel(/first name/i);
    await firstNameInput.fill('Saif');

    const lastNameInput = page.getByLabel(/last name/i);
    await lastNameInput.fill('Afzal');

    const postalCodeInput = page.getByLabel(/postal code/i);
    await postalCodeInput.fill('');

    const continueButton = page.getByRole('button', { name: /continue/i });
    await expect(continueButton).toBeDisabled();

    const errorContainer = page.getByTestId('error');
    await expect(errorContainer).toBeVisible();
    await expect(errorContainer).toContainText('Postal Code is required');
  });

  test('should allow checkout with all required fields filled', async ({ page }) => {
    await page.getByRole('button', { name: /add to cart/i }).click();
    await page.getByRole('button', { name: /add to cart/i }).click();
    await page.getByRole('button', { name: /add to cart/i }).click();
    await page.getByRole('button', { name: /checkout/i }).click();

    const firstNameInput = page.getByLabel(/first name/i);
    await firstNameInput.fill('Saif');

    const lastNameInput = page.getByLabel(/last name/i);
    await lastNameInput.fill('Afzal');

    const postalCodeInput = page.getByLabel(/postal code/i);
    await postalCodeInput.fill('12345');

    const continueButton = page.getByRole('button', { name: /continue/i });
    await expect(continueButton).not.toBeDisabled();

    const errorContainer = page.getByTestId('error');
    await expect(errorContainer).not.toBeVisible();
  });
});
